changeSet.sql:
DROP FUNCTION nexus.create_tenant_partitions(regclass, text, boolean);

CREATE FUNCTION nexus.create_tenant_partitions(
    p_parent        regclass,
    p_tenant        text,
    p_force         boolean DEFAULT true,
    p_check_restore boolean DEFAULT true
) RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
SET lock_timeout = '2s'
AS $fn$
DECLARE
    v_created integer := 0;
    r         record;
BEGIN
    IF p_tenant IS NULL THEN
        RAISE EXCEPTION 'nexus.create_tenant_partitions: a tenant is required'
            USING ERRCODE = 'null_value_not_allowed';
    END IF;
    PERFORM nexus.partition_parent_check(p_parent);
    -- p_force = false exists for the walk, which fills the *_new parents with FORCE ROW LEVEL SECURITY off.
    -- This function is SECURITY DEFINER and nexus_svc may call it, so on a live parent it would make leaves
    -- without FORCE: refused there.
    IF NOT p_force AND (SELECT c.relname FROM pg_catalog.pg_class c WHERE c.oid = p_parent) !~ '_new$' THEN
        RAISE EXCEPTION 'nexus.create_tenant_partitions: p_force = false is accepted only for a *_new parent, not %', p_parent
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    -- The common case, a second token for a tenant that already has every leaf: ONE catalog query, no lock taken.
    -- A concurrent first creation is invisible here until it commits, so the caller falls through to the advisory
    -- lock below and waits for it (bounded by lock_timeout) instead of racing it.
    IF NOT EXISTS (
        SELECT 1
          FROM pg_catalog.pg_inherits i
         WHERE i.inhparent = p_parent
           AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_inherits j
                            WHERE j.inhparent = i.inhrelid
                              AND nexus.partition_bound_value(j.inhrelid) = p_tenant)
    ) THEN
        RETURN 0;
    END IF;
    -- The slow path runs DDL. A tenant restore load (RDR-248) holds the restore-load key exclusively for the whole
    -- load and writes into the partitions this path locks ACCESS EXCLUSIVE: refuse at once instead of queueing
    -- behind it. The shared lock is held to the end of this transaction, so a load that starts meanwhile finds
    -- the key taken and retries its own try-lock. Read-only here: the key text is RestoreLoadLock.KEY_NAME.
    IF p_check_restore AND NOT pg_catalog.pg_try_advisory_xact_lock_shared(
            pg_catalog.hashtextextended('nexus.restore_load', 0)) THEN
        RAISE EXCEPTION 'nexus.create_tenant_partitions: a tenant restore load is running, retry when it ends'
            USING ERRCODE = 'lock_not_available';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('nexus.create_tenant_partitions:' || p_tenant, 0));
    FOR r IN
        SELECT i.inhrelid::pg_catalog.regclass AS mp
          FROM pg_catalog.pg_inherits i
          JOIN pg_catalog.pg_class c ON c.oid = i.inhrelid
         WHERE i.inhparent = p_parent
         ORDER BY c.relname
    LOOP
        IF nexus.partition_ensure_leaf(p_parent, r.mp, p_tenant, p_force) THEN
            v_created := v_created + 1;
        END IF;
    END LOOP;
    RETURN v_created;
END
$fn$;

REVOKE EXECUTE ON FUNCTION nexus.create_tenant_partitions(regclass, text, boolean, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION nexus.create_tenant_partitions(regclass, text, boolean, boolean) TO nexus_svc;

